Actionscript.script:
function r2(n) {
	return Math.round(n * 100) / 100;
}
function info(mc) {
	return mc._name + ": x=" + r2(mc._x) + " y=" + r2(mc._y) + " xscale=" + r2(mc._xscale) +
		" yscale=" + r2(mc._yscale) + " rotation=" + r2(mc._rotation);
}
trace("groups: frame 1");
trace(info(ingroup_mc));
trace(info(nested_mc));
trace(info(clip_mc));
trace(info(clip_mc.inclip_mc));
